        if op=="sha256":
            r,p=self.safe_path(project,q.get("path"),True)
            if not p.is_file(): raise FileNotFoundError(str(p))
            return {"path":q.get("path"),"sha256":self.sha256(p)}
        if op=="write_file":
            r,p=self.safe_path(project,q.get("path")); content=q.get("content")
            if not isinstance(content,str): raise ValueError("content must be string")
            mode=q.get("mode","rewrite"); p.parent.mkdir(parents=True,exist_ok=True)
            with self.lock_for(p):
