        if op=="edit_block":
            r,p=self.safe_path(project,q.get("path"),True); old=q.get("old_string"); new=q.get("new_string"); expected=int(q.get("expected_replacements",1))
            if not isinstance(old,str) or not old: raise ValueError("old_string required")
