        if op=="start_process":
            cwd_rel=q.get("cwd","."); r,cwd=self.safe_path(project,cwd_rel,True)
            if not cwd.is_dir(): raise NotADirectoryError(cwd_rel)
            argv=self.validate_argv(project,q.get("argv"),cwd); sid=q.get("session_id") or ("s-"+uuid.uuid4().hex[:12])
            if not all(c.isalnum() or c in "._-" for c in sid): raise ValueError("invalid session_id")
            with self.session_lock:
                d=SESSIONS/sid
                if d.exists():
                    old=self.session_meta(sid)
                    same=(old.get('argv')==argv and old.get('cwd')==str(cwd.relative_to(r)) and old.get('project')==project)
                    if same: return self.session_snapshot(old)
                    if self.process_alive(old['pid']): raise RuntimeError('session already running')
                    raise RuntimeError('session_id already used with different command')
                d.mkdir(parents=True,exist_ok=True); fifo=d/"stdin.fifo"
                if fifo.exists(): fifo.unlink()
                os.mkfifo(fifo,0o600); in_fd=os.open(fifo,os.O_RDWR)
                out_f=open(d/"stdout.log","ab",buffering=0); err_f=open(d/"stderr.log","ab",buffering=0)
                env=os.environ.copy(); env["PYTHONUNBUFFERED"]="1"
                proc=subprocess.Popen(argv,cwd=str(cwd),stdin=in_fd,stdout=out_f,stderr=err_f,start_new_session=True,env=env)
                os.close(in_fd); out_f.close(); err_f.close()
                meta={"session_id":sid,"pid":proc.pid,"argv":argv,"cwd":str(cwd.relative_to(r)),"project":project,"created_at":now(),"stdin_fifo":str(fifo)}
                (d/"meta.json").write_text(json.dumps(meta,indent=2),encoding="utf-8")
            time.sleep(min(max(float(q.get("initial_wait_seconds",0.3)),0),3)); return self.session_snapshot(meta)
        if op=="read_process_output":
            sid=q.get("session_id"); m=self.session_meta(sid); d=SESSIONS/sid
            return {"session":self.session_snapshot(m),"stdout":self.read_log(d/"stdout.log",q.get("offset",0),q.get("length",400)),"stderr":self.read_log(d/"stderr.log",q.get("offset",0),q.get("length",400))}
        if op=="interact_with_process":
            sid=q.get("session_id"); data=q.get("input")
            if not isinstance(data,str): raise ValueError("input must be string")
            m=self.session_meta(sid)
            if not self.process_alive(m["pid"]): raise RuntimeError("process is not running")
            if q.get("append_newline",True) and not data.endswith("\n"): data+="\n"
            fd=os.open(m["stdin_fifo"],os.O_WRONLY|os.O_NONBLOCK)
            try: os.write(fd,data.encode())
            finally: os.close(fd)
            time.sleep(min(max(float(q.get("wait_seconds",0.25)),0),3))
            return self.execute({"op":"read_process_output","session_id":sid,"offset":-80,"length":80,"project":m["project"]})
        if op=="terminate_process":
            sid=q.get("session_id"); m=self.session_meta(sid); pid=int(m["pid"])
            if not self.process_alive(pid): return {"session_id":sid,"pid":pid,"terminated":False,"already_stopped":True}
            sig=signal.SIGKILL if str(q.get("signal","TERM")).upper()=="KILL" else signal.SIGTERM; os.killpg(pid,sig)
            return {"session_id":sid,"pid":pid,"terminated":True}
        if op=="list_sessions":
            rows=[]
            for p in sorted(SESSIONS.glob("*/meta.json")):
                try: rows.append(self.session_snapshot(json.loads(p.read_text(encoding="utf-8"))))
                except Exception: pass
            return {"sessions":rows[-500:]}
        if op=="signal_project_process":
            pid=int(q.get("pid")); cmd=self.process_command(pid)
            if not cmd: return {"pid":pid,"signaled":False,"reason":"not running"}
            if str(self.project_root(project)) not in cmd: raise PermissionError("refusing to signal non-project process")
            sig_name=str(q.get("signal","TERM")).upper(); sig={"TERM":signal.SIGTERM,"KILL":signal.SIGKILL,"INT":signal.SIGINT}.get(sig_name)
            if sig is None: raise ValueError("signal must be TERM, INT, or KILL")
            os.kill(pid,sig); return {"pid":pid,"signaled":True,"signal":sig_name,"command":cmd[:4000]}
        raise PermissionError(f"op not allowed: {op}")
    def enqueue(self,req):
        tid=req.get("id") or ("q-"+uuid.uuid4().hex)
        payload=json.dumps(req,ensure_ascii=False,separators=(",",":"))
        with self.db_lock:
            row=self.db_conn.execute("SELECT request_json FROM tasks WHERE id=?",(tid,)).fetchone()
            if row:
                if row[0] != payload:
                    raise RuntimeError("task id collision with different payload")
                return tid
            self.db_conn.execute(
                "INSERT INTO tasks(id,created,updated,status,request_json) VALUES(?,?,?,?,?)",
                (tid,time.time(),time.time(),"queued",payload)
            )
        return tid
    def claim(self):
        with self.db_lock:
            row=self.db_conn.execute(
                "SELECT id,request_json FROM tasks WHERE status='queued' ORDER BY created LIMIT 1"
            ).fetchone()
            if not row:
                return None
            changed=self.db_conn.execute(
                "UPDATE tasks SET status='running',updated=? WHERE id=? AND status='queued'",
                (time.time(),row[0])
            ).rowcount
            return row if changed==1 else None
    def finish(self,tid,result):
        raw=json.dumps(result,ensure_ascii=False,separators=(",",":"))
        status="done" if result.get("ok") else "error"
        with self.db_lock:
            self.db_conn.execute(
                "UPDATE tasks SET status=?,result_json=?,updated=? WHERE id=?",
                (status,raw,time.time(),tid)
            )
    def task_result(self,tid):
        with self.db_lock:
            row=self.db_conn.execute(
                "SELECT status,result_json,created,updated FROM tasks WHERE id=?",(tid,)
            ).fetchone()
        if not row:
            return None
        return {"id":tid,"status":row[0],"result":json.loads(row[1]) if row[1] else None,
                "created":row[2],"updated":row[3]}
    def worker(self,n):
        log(f"worker {n} start")
        while True:
            try:
                row=self.claim()
                if not row: time.sleep(0.05); continue
                tid,raw=row; req=json.loads(raw)
                try: ans={"ok":True,"id":tid,"data":self.execute(req),"completed_at":now()}
                except Exception as e: ans={"ok":False,"id":tid,"error":type(e).__name__,"message":str(e),"completed_at":now()}
                self.finish(tid,ans)
            except Exception as e:
                log(f"worker {n} error {type(e).__name__}: {e}"); time.sleep(0.2)

class CommanderHTTPServer(ThreadingHTTPServer):
    request_queue_size = 512
    daemon_threads = True
    allow_reuse_address = True
    max_active_requests = 24

    def __init__(self,*args,**kwargs):
        self._request_sem=threading.BoundedSemaphore(self.max_active_requests)
        super().__init__(*args,**kwargs)

    def process_request(self,request,client_address):
        self._request_sem.acquire()
        def runner():
            try:
                self.process_request_thread(request,client_address)
            finally:
                self._request_sem.release()
        threading.Thread(target=runner,daemon=True,name="http-request").start()

class Handler(BaseHTTPRequestHandler):
    server_version="CopyToLiveChatLokal/1.0"
    def log_message(self,fmt,*args): pass
    def cors(self):
        self.send_header("Access-Control-Allow-Origin","*")
        self.send_header("Access-Control-Allow-Headers","Authorization,X-CopyToLive-Token,Content-Type")
        self.send_header("Access-Control-Allow-Methods","GET,POST,OPTIONS")
    def send_json(self,status,obj):
        raw=json.dumps(obj,ensure_ascii=False).encode()
        if len(raw)>MAX_OUTPUT: raw=json.dumps({"ok":False,"error":"ResponseTooLarge"}).encode()
        self.send_response(status); self.send_header("Content-Type","application/json; charset=utf-8"); self.cors(); self.send_header("Content-Length",str(len(raw))); self.end_headers(); self.wfile.write(raw)
    def do_OPTIONS(self): self.send_response(204); self.cors(); self.end_headers()
    def auth(self):
        a=self.headers.get("Authorization",""); t=self.headers.get("X-CopyToLive-Token","")
        return a=="Bearer "+self.server.commander.token or t==self.server.commander.token
    def body(self):
        n=int(self.headers.get("Content-Length","0"))
        if n<=0 or n>MAX_BODY: raise ValueError("invalid body size")
        return json.loads(self.rfile.read(n).decode("utf-8"))
    def do_GET(self):
        path=urlparse(self.path).path
        if path=="/health":
            c=self.server.commander
            return self.send_json(200,{"ok":True,"profile":"Chat - Lokal","transport":"localhost-only","workers":c.workers,"time":now()})
        if not self.auth(): return self.send_json(401,{"ok":False,"error":"Unauthorized"})
        if path.startswith("/v1/result/"):
            r=self.server.commander.task_result(path.rsplit("/",1)[-1]); return self.send_json(200 if r else 404,r or {"ok":False,"error":"NotFound"})
        return self.send_json(404,{"ok":False,"error":"NotFound"})
    def do_POST(self):
        if not self.auth(): return self.send_json(401,{"ok":False,"error":"Unauthorized"})
        path=urlparse(self.path).path
        try: req=self.body()
        except Exception as e: return self.send_json(400,{"ok":False,"error":type(e).__name__,"message":str(e)})
        if path=="/v1/execute":
            rid=req.get("id") or ("r-"+uuid.uuid4().hex)
            try: return self.send_json(200,{"ok":True,"id":rid,"data":self.server.commander.execute(req)})
            except Exception as e: return self.send_json(400,{"ok":False,"id":rid,"error":type(e).__name__,"message":str(e)})
        if path=="/v1/enqueue":
            try: return self.send_json(202,{"ok":True,"id":self.server.commander.enqueue(req),"status":"queued"})
            except Exception as e: return self.send_json(400,{"ok":False,"error":type(e).__name__,"message":str(e)})
        return self.send_json(404,{"ok":False,"error":"NotFound"})

def serve():
    try:
        soft,hard=resource.getrlimit(resource.RLIMIT_NOFILE)
        target=min(4096, hard if hard != resource.RLIM_INFINITY else 4096)
        if soft < target:
            resource.setrlimit(resource.RLIMIT_NOFILE,(target,hard))
    except Exception as e:
        log(f"RLIMIT note: {e}")
    c=Commander()
    for i in range(c.workers): threading.Thread(target=c.worker,args=(i,),daemon=True,name=f"worker-{i}").start()
    srv=CommanderHTTPServer((HOST,c.port),Handler); srv.commander=c
    log(f"ONLINE host={HOST} port={c.port} workers={c.workers} no-github")
    srv.serve_forever(poll_interval=0.1)

if __name__=="__main__":
    ap=argparse.ArgumentParser(); ap.add_argument("--serve",action="store_true"); args=ap.parse_args()
    if args.serve: serve()
    else: print("Use --serve")

#!/usr/bin/env python3
import os, sys, json, time, threading, queue, uuid
from pathlib import Path
from datetime import datetime, timezone
import importlib.util
from http.server import ThreadingHTTPServer
from urllib.parse import urlparse

HERE=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location("chat_lokal_base",HERE/"base_commander.py")
base=importlib.util.module_from_spec(spec); spec.loader.exec_module(base)

HOME=Path.home()/".copytolive-chat-lokal"
base.HOME=HOME
base.CONFIG=HOME/"config.json"
base.TOKEN_FILE=HOME/"token"
base.LOG_FILE=HOME/"chat-lokal.log"
base.SESSIONS=HOME/"sessions"
HOME.mkdir(parents=True,exist_ok=True)
base.SESSIONS.mkdir(parents=True,exist_ok=True)

def now():
    return datetime.now(timezone.utc).isoformat()

class ChatCommander(base.Commander):
    def init_db(self):
        self.pending=queue.Queue(maxsize=50000)
        self.state_lock=threading.RLock()
        self.requests={}
        self.results={}
        self.req_journal=HOME/"requests.jsonl"
        self.res_journal=HOME/"results.jsonl"
        for p in (self.req_journal,self.res_journal):
            p.touch(exist_ok=True)
        for line in self.req_journal.read_text(encoding="utf-8",errors="replace").splitlines():
            try:
                x=json.loads(line); self.requests[x["id"]]=x["request"]
            except Exception: pass
        for line in self.res_journal.read_text(encoding="utf-8",errors="replace").splitlines():
            try:
                x=json.loads(line); self.results[x["id"]]=x["result"]
            except Exception: pass
        for tid,req in list(self.requests.items()):
            if tid not in self.results:
                try:self.pending.put_nowait((tid,req))
                except queue.Full: break

    def _append(self,path,obj):
        raw=json.dumps(obj,ensure_ascii=False,separators=(",",":"))+"\n"
        with path.open("a",encoding="utf-8") as f:
            f.write(raw); f.flush()

    def enqueue(self,req):
        tid=req.get("id") or ("q-"+uuid.uuid4().hex)
        with self.state_lock:
            old=self.requests.get(tid)
            if old is not None:
                if old!=req: raise RuntimeError("task id collision with different payload")
                return tid
            self.requests[tid]=req
            self._append(self.req_journal,{"id":tid,"request":req,"at":now()})
            self.pending.put_nowait((tid,req))
        return tid

    def task_result(self,tid):
        with self.state_lock:
            if tid in self.results:
                r=self.results[tid]
                return {"id":tid,"status":"done" if r.get("ok") else "error","result":r}
            if tid in self.requests:
                return {"id":tid,"status":"queued","result":None}
        return None

    def finish(self,tid,result):
        with self.state_lock:
            self.results[tid]=result
            self._append(self.res_journal,{"id":tid,"result":result,"at":now()})

    def worker(self,n):
        base.log(f"chat-local worker {n} start")
        while True:
            try:
                tid,req=self.pending.get(timeout=.5)
            except queue.Empty:
                continue
            try:
                try:
                    data=self.execute(req)
                    ans={"ok":True,"id":tid,"data":data,"completed_at":now()}
                except Exception as e:
                    ans={"ok":False,"id":tid,"error":type(e).__name__,"message":str(e),"completed_at":now()}
                self.finish(tid,ans)
            except Exception as e:
                base.log(f"worker {n} persistence error {type(e).__name__}: {e}")
            finally:
                self.pending.task_done()

class ChatHTTPServer(base.CommanderHTTPServer):
    request_queue_size=2048
    daemon_threads=True
    allow_reuse_address=True

class Handler(base.Handler):
    server_version="CopyToLiveChatLokal/1.0"
    def do_GET(self):
        path=urlparse(self.path).path
        if path=="/health":
            c=self.server.commander
            return self.send_json(200,{
                "ok":True,"profile":"Chat - Lokal","transport":"127.0.0.1 only",
                "third_party":False,"github":False,"workers":c.workers,
                "queued":c.pending.qsize(),"time":now()
            })
        if path=="/v1/stats":
            if not self.auth(): return self.send_json(401,{"ok":False,"error":"Unauthorized"})
            c=self.server.commander
            with c.state_lock:
                return self.send_json(200,{"ok":True,"requests":len(c.requests),
                    "results":len(c.results),"queued":c.pending.qsize(),"workers":c.workers})
        return super().do_GET()

def serve():
    c=ChatCommander()
    for i in range(c.workers):
        threading.Thread(target=c.worker,args=(i,),daemon=True,name=f"chat-local-worker-{i}").start()
    srv=ChatHTTPServer(("127.0.0.1",c.port),Handler)
    srv.commander=c; srv.token=base.TOKEN_FILE.read_text(encoding='utf-8').strip()
    base.log(f"CHAT_LOKAL=ONLINE port={c.port} workers={c.workers} third_party=false")
    srv.serve_forever(poll_interval=.05)

if __name__=="__main__":
    serve()
